    '''        if (is_extern_declaration) {\n            if (!minic_parser_parse_extern_global_after_head(parser,\n                                                             base_type,\n                                                             return_type,\n                                                             name_span,\n                                                             section_name,\n                                                             section_name_length,\n                                                             has_section,\n                                                             object_explicit_alignment,\n                                                             visibility,\n                                                             has_visibility)) {\n                return false;\n            }\n            return apply_external_object_weak(parser, name_span, object_is_weak);\n        }''',
